-- A Bible that lives in our own database.
--
-- Churches put scripture on the screen every single service, and until now the
-- only way to do it in SagipMusica was to type the verse into a song section
-- and hope nobody fat-fingered it. This migration adds the text itself, so
-- "John 3:16" is something the presenter looks up rather than something they
-- transcribe.
--
-- The verses are NOT in this file. 0021_bible_kjv_verses.sql carries the
-- 31,102 rows of the 1769 Authorized Version and is generated by
-- scripts/generate-bible-migration.mjs. What is here is the shape, the 66
-- books, and the rules -- the parts a person reads and edits by hand.
--
-- Design notes:
--
--  * NO NETWORK CALL, EVER. The alternative -- api.bible, bolls.life, ESV's
--    API -- puts somebody else's uptime, rate limit and API key in the path of
--    a verse going on the screen mid-sermon, in buildings whose internet is a
--    phone hotspot. Our own table answers in a millisecond and answers when
--    the line is down. It also means the desktop build can ship the same rows
--    in a local SQLite file and behave identically offline, which is the next
--    thing to be built.
--
--  * TRANSLATIONS ARE A TABLE, not a column we will regret. Only the KJV is
--    seeded today, but this is Philippine churches: Ang Dating Biblia and the
--    Magandang Balita Biblia are going to be asked for, and asked for soon.
--    Adding one then is an insert into bible_translations plus a generated
--    verse file -- no schema change, no app change, no re-write of the
--    reference parser.
--
--  * BOOKS ARE SHARED ACROSS TRANSLATIONS. bible_books has no translation_id:
--    all 66 books, their order and their ids are the same in every Protestant
--    Bible, and duplicating them per translation would only create the
--    possibility of them disagreeing. The cost is that a Tagalog translation's
--    book names are not stored yet. That is a display concern, and when it
--    arrives it belongs in a bible_book_names(translation_id, book_id, name)
--    side table -- not in a second copy of the canon.
--
--  * COUNTS ARE DERIVED. There is no chapter_count column on bible_books and
--    no verse_count column anywhere, for the same reason 0018 refuses to store
--    pin counts: a cached count is wrong the first time a row moves and
--    nothing says so. The bible_chapters view below aggregates them, and it is
--    small enough (1,189 rows for the KJV) that the app fetches the whole
--    thing once and builds every chapter and verse grid from it offline.
--
--  * READ-ONLY TO EVERYONE. There is a select policy and there are no others,
--    so no signed-in user and no admin can write a word of it -- scripture
--    changes when a migration says so and not otherwise. anon can read as well
--    as authenticated, because the projector window (see AppRoutes) runs
--    without a session and the marketing site may want a verse one day.
--    Nothing here is private; it is the best-known text in the world.

-- ============================================================================
-- 1. Translations
-- ============================================================================

create table if not exists bible_translations (
  -- Short, stable and human-readable, because it appears in the generated
  -- verse files, in URLs (/bible?translation=kjv) and in bug reports.
  id text primary key
    check (id ~ '^[a-z0-9-]{2,16}$'),

  name text not null,

  -- What the projector prints under the reference: "John 3:16 (KJV)".
  abbreviation text not null,

  -- ISO 639-1. 'en' today; 'tl' is the one to expect next.
  language_code text not null default 'en'
    check (language_code ~ '^[a-z]{2}$'),

  -- The year of the specific revision, not of the first edition. The KJV row
  -- says 1769 -- the Blayney revision every modern "KJV" actually is -- and
  -- not 1611, so there is never a question about which text this is.
  year integer,

  -- Free text on purpose. Every translation we can legally ship is public
  -- domain, but the reason differs by jurisdiction and is worth recording
  -- next to the text rather than in a commit message.
  license text not null,

  -- Where the rows came from, so the import is reproducible by someone who
  -- was not here when it was done.
  source_url text,

  -- One translation is the one a church gets when it has not chosen. Enforced
  -- as at-most-one by the partial unique index below.
  is_default boolean not null default false,

  created_at timestamptz not null default now()
);

-- Partial unique index: every indexed row has is_default = true, so at most
-- one row can be indexed at a time. Rows with false are not in the index and
-- are unconstrained.
create unique index if not exists bible_translations_one_default
  on bible_translations (is_default) where is_default;

insert into bible_translations (id, name, abbreviation, language_code, year, license, source_url, is_default)
values (
  'kjv',
  'King James Version',
  'KJV',
  'en',
  1769,
  'Public domain. The 1769 Blayney revision of the 1611 Authorized Version is '
    || 'out of copyright worldwide. The Crown letters patent that still cover '
    || 'the KJV restrict printing within the United Kingdom only, and do not '
    || 'reach the text itself or its use elsewhere.',
  'https://github.com/farskipper/kjv',
  true
)
on conflict (id) do update set
  name = excluded.name,
  abbreviation = excluded.abbreviation,
  language_code = excluded.language_code,
  year = excluded.year,
  license = excluded.license,
  source_url = excluded.source_url;

-- ============================================================================
-- 2. Books
--
-- Fixed at 66 rows, in canonical order, with the id doubling as the sort key.
-- The ids are load-bearing: the generated verse file writes them literally,
-- so renumbering these would silently re-attach every verse to the wrong book.
-- ============================================================================

create table if not exists bible_books (
  -- 1 = Genesis .. 66 = Revelation. Deliberately not a uuid: this is a closed,
  -- ordered, universally agreed list, and an integer that sorts into reading
  -- order is worth more here than a surrogate key.
  id smallint primary key
    check (id between 1 and 66),

  name text not null unique,

  abbreviation text not null unique,

  testament text not null
    check (testament in ('old', 'new')),

  -- Everything else a person might type for this book: older names, common
  -- short forms, and the spellings that show up when somebody is typing fast
  -- on a phone at the back of the sanctuary. The reference parser in
  -- src/features/bible/reference.ts normalises both sides before comparing --
  -- case, spaces, punctuation and "I/II/III" vs "1/2/3" are all handled there
  -- -- so these only need to carry spellings that are genuinely different
  -- words, not every capitalisation of them.
  aliases text[] not null default '{}'
);

insert into bible_books (id, name, abbreviation, testament, aliases) values
