  name = excluded.name,
  abbreviation = excluded.abbreviation,
  testament = excluded.testament,
  aliases = excluded.aliases;

-- An alias that also belongs to another book makes the parser pick one of two
-- books arbitrarily, and the loser is a verse that quietly cannot be looked up
-- by the name its church uses for it. Cheap to check once, here, rather than
-- discovering it from a support message.
do $$
declare
  clash text;
begin
  -- Tokens are de-duplicated WITHIN a book first. Plenty of books are their
  -- own abbreviation -- Job, Ruth, Acts, Jude -- and that is not a clash; two
  -- different books answering to the same token is.
  select string_agg(token, ', ') into clash from (
    select token from (
      select distinct id, lower(btrim(token)) as token from (
        select id, name as token from bible_books
        union all select id, abbreviation from bible_books
        union all select id, unnest(aliases) from bible_books
      ) raw_tokens
    ) per_book
    group by token
    having count(*) > 1
  ) duplicates;

  if clash is not null then
    raise exception 'bible_books has ambiguous name/abbreviation/alias tokens: %', clash;
  end if;
end $$;

-- ============================================================================
-- 3. Verses
-- ============================================================================

create table if not exists bible_verses (
  translation_id text not null
    references bible_translations(id) on delete cascade,
  book_id smallint not null
    references bible_books(id),
  chapter smallint not null check (chapter > 0),
  verse smallint not null check (verse > 0),

  text text not null
    check (length(btrim(text)) > 0),

  -- True where the printed edition starts a new paragraph -- the pilcrow in a
  -- pew Bible. Kept because it is real typographic information about the text
  -- and it costs a bit, not because anything reads it yet.
  paragraph boolean not null default false,

  -- The natural key IS the key. A surrogate id would add a column, an index
  -- and a sequence to a table whose rows are identified by exactly these four
  -- values in every citation ever written. The column order matters: it puts
  -- the index in reading order, so fetching a chapter is one range scan.
  primary key (translation_id, book_id, chapter, verse)
);

-- Full-text search over the words. This is the "find the verse when you can
-- only remember how it goes" half of the feature, and it is why the text lives
-- in Postgres instead of a JSON file in the bundle.
--
-- 'english' stemming is right for the KJV even with its archaic forms: the
-- snowball stemmer folds "loved"/"loveth"-adjacent forms imperfectly but
-- usefully, and a searcher typing "comfort" should find "comforteth". A
-- Tagalog translation added later will want its own configuration on its own
-- rows; that is a reason to make this per-translation when it happens, not a
-- reason to leave it untyped now.
alter table bible_verses
  add column if not exists search tsvector
  generated always as (to_tsvector('english', text)) stored;

create index if not exists bible_verses_search
  on bible_verses using gin (search);

-- Search results are ordered canonically -- Genesis before Revelation -- and
-- the planner needs this to sort a few thousand matches without a full sort of
-- the table.
create index if not exists bible_verses_canonical
  on bible_verses (translation_id, book_id, chapter, verse);

-- ============================================================================
-- 4. The chapter index
--
-- One row per chapter: which chapters a book has, and how many verses each
-- holds. That is everything the chapter and verse grids in the picker need,
-- it is 1,189 rows for the KJV, and it is derived rather than stored, so it
-- cannot drift away from the verses it describes.
-- ============================================================================

create or replace view bible_chapters
with (security_invoker = true) as
  select
    translation_id,
    book_id,
    chapter,
    count(*)::integer as verse_count
  from bible_verses
  group by translation_id, book_id, chapter;

-- ============================================================================
-- 5. Access
--
-- Select for everyone, write for no one. Note there is deliberately no insert,
-- update or delete policy on any of these tables: with RLS on and no policy,
-- those statements match zero rows for every role that goes through RLS. The
-- migration runner and service_role bypass RLS, which is exactly the intended
-- set of writers.
-- ============================================================================

alter table bible_translations enable row level security;
alter table bible_books enable row level security;
alter table bible_verses enable row level security;

drop policy if exists "bible_translations_read" on bible_translations;
create policy "bible_translations_read" on bible_translations
  for select to anon, authenticated using (true);

drop policy if exists "bible_books_read" on bible_books;
create policy "bible_books_read" on bible_books
  for select to anon, authenticated using (true);

drop policy if exists "bible_verses_read" on bible_verses;
create policy "bible_verses_read" on bible_verses
  for select to anon, authenticated using (true);

-- Explicit rather than relying on whatever the default privileges happen to
-- be, and narrow: select only, so a future default that hands out more does
-- not quietly apply to scripture.
revoke all on bible_translations from anon, authenticated;
revoke all on bible_books from anon, authenticated;
revoke all on bible_verses from anon, authenticated;
revoke all on bible_chapters from anon, authenticated;

grant select on bible_translations to anon, authenticated;
grant select on bible_books to anon, authenticated;
grant select on bible_verses to anon, authenticated;
grant select on bible_chapters to anon, authenticated;
